            <path d="M381 255 L444 200 L508 267 L469 279 L439 249 L414 287 Z" fill="#f8fafc"/>
            <path d="M696 444 L804 255 L923 444 Z" fill="#dbeafe"/>
            <path d="M789 292 L846 240 L893 298 L869 305 L848 279 L824 314 Z" fill="#f8fafc"/>
            <ellipse cx="602" cy="746" rx="282" ry="56" fill="url(#glow)" fill-opacity=".5"/>
            <path d="M560 548 C516 596 492 636 474 705 C462 750 452 804 446 900 L640 900 C634 824 629 766 622 713 C614 660 595 598 560 548 Z" fill="#0ea5e9" fill-opacity=".22"/>
            <rect x="102" y="108" width="172" height="38" rx="19" fill="#ffffff" fill-opacity=".18"/>
            <rect x="102" y="108" width="92" height="38" rx="19" fill="#ffffff" fill-opacity=".34"/>
          </svg>
        `);

      const App = () => `
        <div class="page">
          <header class="topbar">
            <div>
              <p class="eyebrow">Library preview</p>
              <h1 class="brand">Image details</h1>
              <p class="subhead">Review the image before removing it from your library. The delete action opens a confirmation dialog so the choice is explicit and reversible until confirmed.</p>
            </div>
          </header>

          <main id="main" class="shell">
            ${ImagePreview()}
          </main>

          <p id="status" class="status" role="status" aria-live="polite" aria-atomic="true"></p>
        </div>

        ${DeleteDialog()}
      `;

      const ImagePreview = () => `
        <section class="card preview" aria-labelledby="preview-title">
          <div class="art">
            <img src="${imageData}" alt="Stylized mountain lake at dusk with glowing reflections and dark alpine silhouettes" />
            <div class="art-overlay" aria-hidden="true">
              <span class="chip">Preview</span>
              <span>1.8 MB · 2400 × 1800</span>
            </div>
          </div>

          <div class="details">
            <div class="meta">
              <p class="label">Selected image</p>
              <h2 id="preview-title" class="filename">summit-lake-at-dusk.jpg</h2>
              <p class="description">
                This image is stored in your personal library and can be removed at any time.
                Use the delete control below to confirm the removal action.
              </p>
            </div>

            <div class="action-row">
              <button type="button" class="button button--secondary">Keep image</button>
              <button type="button" class="trigger button button--danger" data-open-dialog>
                Delete image
              </button>
            </div>
          </div>
        </section>
      `;

      const DeleteDialog = () => `
        <dialog id="delete-dialog" aria-labelledby="delete-title" aria-describedby="delete-body">
          <form method="dialog" class="dialog-inner">
            <div>
              <h2 id="delete-title" class="dialog-title">Delete this image?</h2>
              <p id="delete-body" class="dialog-body">
                This will remove <strong>summit-lake-at-dusk.jpg</strong> from your library.
                The image can be re-uploaded later, but this change will take effect immediately.
              </p>
            </div>

            <div class="dialog-actions">
              <button type="submit" value="cancel" class="button button--secondary" autofocus>Cancel</button>
              <button type="submit" value="confirm" class="button button--danger">Delete image</button>
            </div>
          </form>
        </dialog>
      `;

      const root = document.getElementById("app");
      root.innerHTML = App();

      const dialog = document.getElementById("delete-dialog");
      const trigger = document.querySelector(".trigger");
      const status = document.getElementById("status");

      trigger.addEventListener("click", () => {
        dialog.showModal();
      });

      dialog.addEventListener("close", () => {
        if (dialog.returnValue === "confirm") {
          status.textContent = "Image deleted from your library.";
        }
      });
    </script>
