       }

       .button--secondary {
         background: #edf2ff;
         color: var(--brand-strong);
         border-color: rgba(37, 99, 235, 0.18);
       }

       .button--danger {
         background: linear-gradient(180deg, #ef4444, var(--danger));
         color: #ffffff;
         box-shadow: 0 12px 24px rgba(220, 38, 38, 0.24);
