const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');
const axe = require('axe-core');

(async() => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  const html = fs.readFileSync(path.resolve('index.html'), 'utf8');
  await page.setContent(html, { waitUntil: 'load' });
  await page.addScriptTag({ content: axe.source });

  const trigger = page.locator('.trigger');
  const dialog = page.locator('#delete-dialog');
  const result = await page.evaluate(async () => {
    const axeResults = await window.axe.run();
    return {
      dialogOpen: document.getElementById('delete-dialog').open,
      triggerText: document.querySelector('.trigger')?.textContent.trim(),
      axeViolations: axeResults.violations.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
    };
  });

  await trigger.click();
  const openState = await dialog.evaluate(el => el.open);
  await page.getByRole('button', { name: 'Cancel' }).click();
  const closedState = await dialog.evaluate(el => el.open);

  console.log(JSON.stringify({
    initialDialogOpen: result.dialogOpen,
    triggerText: result.triggerText,
    openState,
    closedState,
    axeViolations: result.axeViolations,
  }, null, 2));

  await browser.close();
})();
