  const dialogOpen = await page.locator('#delete-dialog').evaluate(el => el.open);
  await page.keyboard.press('Escape');
  const dialogClosed = await page.locator('#delete-dialog').evaluate(el => el.open);

  console.log(JSON.stringify({ base, dialogOpen, dialogClosed }, null, 2));
  await browser.close();
})();
